{"type":"message_update","usage":{"input":1211,"output":3612,"cacheRead":10240,"cacheWrite":0,"reasoning":18,"totalTokens":15063,"cost":{"input":0,"output":0,"cacheRead":0,"cacheWrite":0,"total":0}},"assistantMessageEvent":{"type":"toolcall_end","contentIndex":2,"toolCall":{"type":"toolCall","id":"call_84a56a8570c14438b4931bc2","name":"write","arguments":{"content":"/**
 * Unit tests for src/csv.mjs — parseCatalog(csvText).
 * Node built-in test runner only: node --test tests/csv.test.mjs
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { parseCatalog } from '../src/csv.mjs';

const H = 'id,name,price\n';

// ---------------------------------------------------------------------------
// Basic parsing & contract shape
// ---------------------------------------------------------------------------

test('parses a simple single-row catalog', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,Widget,9.99`), [
    { id: '1', name: 'Widget', price: 9.99 },
  ]);
});

test('parses multiple rows (with and without trailing newline)', () => {
  const expected = [
    { id: '1', name: 'Widget', price: 9.99 },
    { id: '2', name: 'Gadget', price: 0.5 },
  ];
  assert.deepStrictEqual(parseCatalog(`${H}1,Widget,9.99\n2,Gadget,0.5\n`), expected);
  assert.deepStrictEqual(parseCatalog(`${H}1,Widget,9.99\n2,Gadget,0.5`), expected);
});

test('returns objects with exactly the id/name/price keys and correct types', () => {
  const items = parseCatalog(`${H}7,Thing,3`);
  assert.equal(items.length, 1);
  assert.deepStrictEqual(Object.keys(items[0]).sort(), ['id', 'name', 'price']);
  assert.equal(typeof items[0].id, 'string');
  assert.equal(typeof items[0].name, 'string');
  assert.equal(typeof items[0].price, 'number');
});

test('header-only input yields an empty array', () => {
  assert.deepStrictEqual(parseCatalog('id,name,price'), []);
  assert.deepStrictEqual(parseCatalog('id,name,price\n'), []);
  assert.deepStrictEqual(parseCatalog('id,name,price\r\n'), []);
});

test('id fields stay strings (leading zeros preserved)', () => {
  assert.deepStrictEqual(parseCatalog(`${H}00123,Zip,1`), [
    { id: '00123', name: 'Zip', price: 1 },
  ]);
});

test('price 0 and zero-like values are accepted', () => {
  assert.deepStrictEqual(parseCatalog(`${H}a,Z,0\nb,Z,0.0\nc,Z,+0`), [
    { id: 'a', name: 'Z', price: 0 },
    { id: 'b', name: 'Z', price: 0 },
    { id: 'c', name: 'Z', price: 0 },
  ]);
});

// ---------------------------------------------------------------------------
// Empty / whitespace-only input
// ---------------------------------------------------------------------------

test('empty string input returns no items (not an error)', () => {
  assert.deepStrictEqual(parseCatalog(''), []);
});

test('whitespace-only input returns no items (not an error)', () => {
  for (const ws of [' ', '\n', '\r\n', '  \t \n \r\n  ', '\r']) {
    assert.deepStrictEqual(parseCatalog(ws), [], `input was ${JSON.stringify(ws)}`);
  }
});

// ---------------------------------------------------------------------------
// Quoted fields: commas, escaped quotes, newlines
