  assert.deepEqual(searchCatalog(items, { query: 'widget widget widget' }), []);
});

test('matching combined with price bounds (query "widget", 15..150)', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { query: 'widget', minPrice: 15, maxPrice: 150 })), ['c3', 'e5']);
});

// ---------------------------------------------------------------------------
// Inclusive price bounds
// ---------------------------------------------------------------------------

test('minPrice bound is inclusive', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { minPrice: 20 });
  assert.deepEqual(ids(result), ['b2', 'c3', 'e5', 'f6']); // b2 has price exactly 20
});

test('maxPrice bound is inclusive', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { maxPrice: 30.5 });
  assert.deepEqual(ids(result), ['a1', 'b2', 'c3', 'd4']); // c3 has price exactly 30.5
});

test('minPrice === maxPrice keeps only exact-price items', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 10, maxPrice: 10 })), ['a1']);
});

test('price bounds with min 0 and max Infinity match everything', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 0, maxPrice: Infinity })), ids(items));
});

test('float boundary: price 19.999 excluded by minPrice 20, included by 19.99', () => {
  const items = [{ id: 'f', name: 'x', price: 19.999 }];
  assert.deepEqual(searchCatalog(items, { minPrice: 20 }), []);
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 19.99 })), ['f']);
});

// ---------------------------------------------------------------------------
// Order stability & input preservation
// ---------------------------------------------------------------------------

test('input order is preserved, not sorted by price or name', () => {
  const items = [
    { id: 'hi1', name: 'widget', price: 1000 },
    { id: 'lo1', name: 'Widget', price: 1 },
    { id: 'mid', name: 'WIDGET', price: 500 },
    { id: 'other', name: 'gizmo', price: 300 },
    { id: 'hi2', name: 'widgets', price: 999 },
  ];
  const result = searchCatalog(items, { query: 'widget' });
  assert.deepEqual(ids(result), ['hi1', 'lo1', 'mid', 'hi2']);
});

test('result is a new array but keeps references to the original item objects', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { query: 'widget' });
  assert.notStrictEqual(result, items);
  assert.strictEqual(result[0], items[0]);
  assert.strictEqual(result[1], items[2]);
  assert.strictEqual(result[2], items[4]);
});

test('full match result is still a distinct array from the input', () => {
  const items = sampleItems();
  const result = searchCatalog(items);
  assert.notStrictEqual(result, items);
  assert.deepEqual(result, items);
});

test('input array and its objects are never mutated (deep equality before/after)', () => {
  const items = sampleItems();
  items[0].tags = ['keep', 'me']; // extra properties must survive untouched
  const snapshot = structuredClone(items);
  searchCatalog(items, { query: 'W', minPrice: 5, maxPrice: 50 });
  searchCatalog(items);
  searchCatalog(items, { query: 'no-such-thing' });
  assert.deepEqual(items, snapshot);
  // Order of input itself is unchanged:
  assert.deepEqual(ids(items), ['a1', 'b2', 'c3', 'd4', 'e5', 'f6']);
  // Result operations do not write back into the input:
  const result = searchCatalog(items, { query: 'widget' });
  result.push({ id: 'injected', name: 'junk', price: -1 });
  assert.equal(items.length, 6);
});

test('empty input array returns empty array', () => {
  const items = [];
  assert.deepEqual(searchCatalog(items, { query: 'anything' }), []);
  assert.deepEqual(searchCatalog(items), []);
});

