test('items with missing/non-string name only match the empty query', () => {
  const items = [
    { id: 'n1', price: 5 },
    { id: 'n2', name: null, price: 5 },
    { id: 'n3', name: 123, price: 5 },
    { id: 'n4', name: '', price: 5 },
  ];
  assert.deepEqual(ids(searchCatalog(items)), ids(items)); // empty query matches all
  assert.deepEqual(searchCatalog(items, { query: 'x' }), []);
});

test('items with non-numeric price are excluded rather than throwing', () => {
