test('non-string query throws Error', () => {
  for (const badQuery of [5, null, true, {}, [], NaN]) {
    assert.throws(() => searchCatalog(sampleItems(), { query: badQuery }), Error);
  }
});

test('non-array items throws Error', () => {
  for (const badItems of [null, undefined, 'nope', 42, { id: 'a' }]) {
    assert.throws(() => searchCatalog(badItems), Error);
  }
});

