    throw new TypeError(`${label} must be a number, got ${typeof value}`);
  }
  if (Number.isNaN(value)) {
    throw new TypeError(`${label} must not be NaN`);
  }
  if (value < 0) {
    throw new RangeError(`${label} must not be negative, got ${value}`);
  }
}

export function searchCatalog(items, options = {}) {
