","thinkingSignature":"reasoning_content"},{"type":"toolCall","id":"call_e38161baeff3422d83f21b24","name":"write","arguments":{"path":"src/csv.mjs","content":"/**
 * Dependency-free CSV parser for the catalog toolkit.
 *
 * Public contract (see README.md):
 *   parseCatalog(csvText) -> [{ id: string, name: string, price: number }]
 *
 * - Expected header row: id,name,price
 * - Handles commas inside quoted fields, escaped quotes ("" inside a quoted
 *   field), embedded newlines inside quoted fields, and LF/CRLF/CR line
 *   endings.
 * - Empty or whitespace-only input yields an empty array (not an error).
 * - Fails fast (throws) on: non-string input, missing/invalid header, rows
 *   whose field count is not exactly 3, unterminated quoted fields, stray
 *   text immediately after a closing quote, and prices that are missing,
 *   non-numeric, negative, or non-finite (NaN / Infinity).
 */

const HEADER = ['id', 'name', 'price'];

/**
 * Parse catalog CSV text into an array of {id, name, price} objects.
 * @param {string} csvText
 * @returns {Array<{id: string, name: string, price: number}>}
 */
export function parseCatalog(csvText) {
  if (typeof csvText !== 'string') {
    throw new TypeError(
      `parseCatalog: expected a string, got ${csvText === null ? 'null' : typeof csvText}`
    );
  }

  // Empty or whitespace-only input -> no items, not an error.
  if (csvText.trim() === '') {
    return [];
  }

  const records = parseRecords(csvText);
  const items = [];
  let sawHeader = false;

  for (let i = 0; i < records.length; i++) {
    const fields = records[i];
    const rowNum = i + 1;

    // Skip blank records (e.g. empty lines between rows, or the phantom
    // record after a trailing newline).
    if (fields.length === 1 && fields[0] === '') {
      continue;
    }

    if (!sawHeader) {
      if (
        fields.length !== HEADER.length ||
        fields.some((f, idx) => f !== HEADER[idx])
      ) {
        throw new Error(
          `parseCatalog: invalid or missing header row at row ${rowNum} ` +
            `(expected "id,name,price")`
        );
      }
      sawHeader = true;
      continue;
    }

    if (fields.length !== 3) {
      throw new Error(
        `parseCatalog: malformed row at row ${rowNum}: expected 3 fields, got ${fields.length}`
      );
    }

    const [id, name, priceRaw] = fields;
    items.push({ id, name, price: parsePrice(priceRaw, rowNum) });
  }

  return items;
}

/**
 * Split CSV text into records (arrays of raw string fields) using an
 * RFC-4180-style state machine. Newlines inside quoted fields are treated
 * as field content; unquoted LF, CRLF and lone CR all end a record.
 */
function parseRecords(text) {
  const records = [];
  let fields = [];
  let value = '';
  let inQuotes = false; // currently inside a quoted field
  let quoteClosed = false; // a quoted field just closed; only a delimiter or
  // newline may legally follow the closing quote.

  const endField = () => {
    fields.push(value);
    value = '';
    inQuotes = false;
    quoteClosed = false;
  };

  const endRecord = () => {
    endField();
    records.push(fields);
    fields = [];
  };

  for (let i = 0; i < text.length; i++) {
    const ch = text[i];

    if (inQuotes) {
      if (ch === '"') {
        if (text[i + 1] === '"') {
          value += '"'; // escaped quote ""
          i++;
        } else {
          inQuotes = false;
          quoteClosed = true;
        }
      } else {
        value += ch; // any other char, including newlines, is field content
      }
      continue;
    }

    if (quoteClosed) {
      if (ch === ',') {
        endField();
        continue;
      }
      if (ch === '\n') {
        endRecord();
        continue;
      }
      if (ch === '\r') {
        if (text[i + 1] === '\n') i++;
        endRecord();
        continue;
      }
      throw new Error(
        `parseCatalog: malformed row at row ${records.length + 1}: unexpected character ${JSON.stringify(ch)} after closing quote`
      );
    }

    if (ch === '"' && value === '') {
      // A quote opens a quoted field only at the very start of the field.
      inQuotes = true;
      continue;
    }
    if (ch === ',') {
      endField();
      continue;
    }
    if (ch === '\n') {
      endRecord();
      continue;
    }
    if (ch === '\r') {
      if (text[i + 1] === '\n') i++;
      endRecord();
      continue;
    }
    value += ch;
  }

  if (inQuotes) {
    throw new Error(
      `parseCatalog: malformed row at row ${records.length + 1}: unterminated quoted field at end of input`
    );
  }

  endRecord(); // flush the final (possibly trailing-empty) record
  return records;
}

/**
 * Convert a raw price field to a finite, non-negative number.
 */
function parsePrice(raw, rowNum) {
  const trimmed = raw.trim();
  if (trimmed === '') {
    throw new Error(`parseCatalog: missing price at row ${rowNum}`);
  }
  const price = Number(trimmed);
  if (!Number.isFinite(price)) {
    throw new Error(
      `parseCatalog: non-finite or non-numeric price ${JSON.stringify(raw)} at row ${rowNum}`
    );
  }
  if (price < 0) {
    throw new Error(
      `parseCatalog: negative price ${JSON.stringify(raw)} at row ${rowNum}`
    );
  }
  // "+ 0" normalises a parsed "-0" to +0 so results compare cleanly.
  return price + 0;
}
