 * Unit tests for src/csv.mjs — parseCatalog(csvText).
 * Node built-in test runner only: node --test tests/csv.test.mjs
 */
import { test } from 'node:test';
import assert from 'node:assert/strict';

import { parseCatalog } from '../src/csv.mjs';

const H = 'id,name,price\n';

// ---------------------------------------------------------------------------
// Basic parsing & contract shape
// ---------------------------------------------------------------------------

test('parses a simple single-row catalog', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,Widget,9.99`), [
    { id: '1', name: 'Widget', price: 9.99 },
  ]);
});

test('parses multiple rows (with and without trailing newline)', () => {
  const expected = [
    { id: '1', name: 'Widget', price: 9.99 },
    { id: '2', name: 'Gadget', price: 0.5 },
  ];
  assert.deepStrictEqual(parseCatalog(`${H}1,Widget,9.99\n2,Gadget,0.5\n`), expected);
  assert.deepStrictEqual(parseCatalog(`${H}1,Widget,9.99\n2,Gadget,0.5`), expected);
});

test('returns objects with exactly the id/name/price keys and correct types', () => {
  const items = parseCatalog(`${H}7,Thing,3`);
  assert.equal(items.length, 1);
  assert.deepStrictEqual(Object.keys(items[0]).sort(), ['id', 'name', 'price']);
  assert.equal(typeof items[0].id, 'string');
  assert.equal(typeof items[0].name, 'string');
  assert.equal(typeof items[0].price, 'number');
});

test('header-only input yields an empty array', () => {
  assert.deepStrictEqual(parseCatalog('id,name,price'), []);
  assert.deepStrictEqual(parseCatalog('id,name,price\n'), []);
  assert.deepStrictEqual(parseCatalog('id,name,price\r\n'), []);
});

test('id fields stay strings (leading zeros preserved)', () => {
  assert.deepStrictEqual(parseCatalog(`${H}00123,Zip,1`), [
    { id: '00123', name: 'Zip', price: 1 },
  ]);
});

test('price 0 and zero-like values are accepted', () => {
  assert.deepStrictEqual(parseCatalog(`${H}a,Z,0\nb,Z,0.0\nc,Z,+0`), [
    { id: 'a', name: 'Z', price: 0 },
    { id: 'b', name: 'Z', price: 0 },
    { id: 'c', name: 'Z', price: 0 },
  ]);
});

// ---------------------------------------------------------------------------
// Empty / whitespace-only input
// ---------------------------------------------------------------------------

test('empty string input returns no items (not an error)', () => {
  assert.deepStrictEqual(parseCatalog(''), []);
});

test('whitespace-only input returns no items (not an error)', () => {
  for (const ws of [' ', '\n', '\r\n', '  \t \n \r\n  ', '\r']) {
    assert.deepStrictEqual(parseCatalog(ws), [], `input was ${JSON.stringify(ws)}`);
  }
});

// ---------------------------------------------------------------------------
// Quoted fields: commas, escaped quotes, newlines
// ---------------------------------------------------------------------------

test('commas inside quoted fields do not split the field', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,"Smith, John",2.50`), [
    { id: '1', name: 'Smith, John', price: 2.5 },
  ]);
});

test('escaped quotes ("") inside a quoted field become a single quote', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,"He said ""hi""",3`), [
    { id: '1', name: 'He said "hi"', price: 3 },
  ]);
});

test('quoted field combining commas, escaped quotes and surrounding text', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,"a ""b"", c",1.25`), [
    { id: '1', name: 'a "b", c', price: 1.25 },
  ]);
});

test('field consisting solely of escaped quotes is a single quote char', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,"""",1`), [{ id: '1', name: '"', price: 1 }]);
});

test('empty quoted field becomes empty string', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,"",1`), [{ id: '1', name: '', price: 1 }]);
});

test('quoted id field is supported', () => {
  assert.deepStrictEqual(parseCatalog(`${H}"x,1",Name,2`), [
    { id: 'x,1', name: 'Name', price: 2 },
  ]);
});

test('newlines inside quoted fields are preserved as field content', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,"line1\nline2",2`), [
    { id: '1', name: 'line1\nline2', price: 2 },
  ]);
  assert.deepStrictEqual(parseCatalog(`${H}1,"line1\r\nline2",2`), [
    { id: '1', name: 'line1\r\nline2', price: 2 },
  ]);
});

test('quotes not at field start are literal characters', () => {
  assert.deepStrictEqual(parseCatalog(`${H}1,sa"ty,2`), [
    { id: '1', name: 'sa"ty', price: 2 },
  ]);
});

test('quoted fields keep internal spaces verbatim; unquoted fields are not trimmed', () => {
  const items = parseCatalog(`${H}1,"  padded  ",2\n2, spaced ,3`);
  assert.equal(items[0].name, '  padded  ');
  assert.equal(items[1].name, ' spaced ');
});

// ---------------------------------------------------------------------------
// Line endings
// ---------------------------------------------------------------------------

test('CRLF line endings are handled', () => {
  assert.deepStrictEqual(parseCatalog('id,name,price\r\n1,A,1\r\n2,B,2\r\n'), [
    { id: '1', name: 'A', price: 1 },
    { id: '2', name: 'B', price: 2 },
  ]);
});

test('lone CR line endings are also treated as record separators', () => {
  assert.deepStrictEqual(parseCatalog('id,name,price\r1,A,1\r2,B,2'), [
    { id: '1', name: 'A', price: 1 },
    { id: '2', name: 'B', price: 2 },
  ]);
});

test('trailing newline (LF or CRLF) does not produce a phantom row', () => {
  const expected = [{ id: '1', name: 'A', price: 1 }];
  assert.deepStrictEqual(parseCatalog(`${H}1,A,1\n`), expected);
  assert.deepStrictEqual(parseCatalog(`${H}1,A,1\r\n`), expected);
});

// ---------------------------------------------------------------------------
// Blank lines (interpretation: skipped)
// ---------------------------------------------------------------------------

