import assert from 'node:assert/strict';
import { searchCatalog } from '../src/search.mjs';

// ---------------------------------------------------------------------------
// Fixtures
// ---------------------------------------------------------------------------

function sampleItems() {
  return [
    { id: 'a1', name: 'Widget', price: 10 },
    { id: 'b2', name: 'GADGET Pro', price: 20 },
    { id: 'c3', name: 'super widget deluxe', price: 30.5 },
    { id: 'd4', name: 'Doohickey', price: 0 },
    { id: 'e5', name: 'Widget Widget', price: 100 },
    { id: 'f6', name: 'Sprocket', price: 999.99 },
  ];
}

function ids(list) {
  return list.map((item) => item.id);
}

// ---------------------------------------------------------------------------
// Defaults & empty query
// ---------------------------------------------------------------------------

test('omitting options entirely returns all items (defaults: query="", min=0, max=Infinity)', () => {
  const items = sampleItems();
  const result = searchCatalog(items);
  assert.deepEqual(ids(result), ['a1', 'b2', 'c3', 'd4', 'e5', 'f6']);
});

test('empty object options behave like defaults', () => {
  const items = sampleItems();
  assert.deepEqual(searchCatalog(items, {}), items.filter(() => true));
});

test('explicit empty query matches all items regardless of case', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { query: '' })), ids(items));
});

test('undefined individual options fall back to documented defaults', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { query: undefined, minPrice: undefined, maxPrice: undefined });
  assert.deepEqual(ids(result), ids(items));
});

test('default minPrice of 0 includes items priced exactly 0', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { query: 'Doohickey' });
  assert.deepEqual(ids(result), ['d4']);
});

test('default maxPrice of Infinity includes very large prices', () => {
  const items = [{ id: 'x', name: 'expensive', price: Number.MAX_VALUE }];
  assert.deepEqual(ids(searchCatalog(items, { query: 'expensive' })), ['x']);
});

// ---------------------------------------------------------------------------
// Case-insensitive substring matching
// ---------------------------------------------------------------------------

test('substring match is case-insensitive across all case variants', () => {
  const items = sampleItems();
  const expected = ['a1', 'c3', 'e5']; // everything containing "widget" in any case
  assert.deepEqual(ids(searchCatalog(items, { query: 'widget' })), expected);
  assert.deepEqual(ids(searchCatalog(items, { query: 'WIDGET' })), expected);
  assert.deepEqual(ids(searchCatalog(items, { query: 'Widget' })), expected);
  assert.deepEqual(ids(searchCatalog(items, { query: 'wIdGeT' })), expected);
});

test('matches substrings in the middle of words', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { query: 'IDGET' })), ['a1', 'c3', 'e5']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'pro' })), ['b2']);
});

test('query with spaces matches spaces in name', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { query: 'widget deluxe' })), ['c3']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'Widget Widget' })), ['e5']);
});

test('non-matching query returns empty array', () => {
  const items = sampleItems();
  assert.deepEqual(searchCatalog(items, { query: 'nonexistent' }), []);
});

test('query longer than any name matches nothing', () => {
  const items = sampleItems();
  assert.deepEqual(searchCatalog(items, { query: 'widget widget widget' }), []);
});

test('matching combined with price bounds (query "widget", 15..150)', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { query: 'widget', minPrice: 15, maxPrice: 150 })), ['c3', 'e5']);
});

// ---------------------------------------------------------------------------
// Inclusive price bounds
// ---------------------------------------------------------------------------

test('minPrice bound is inclusive', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { minPrice: 20 });
  assert.deepEqual(ids(result), ['b2', 'c3', 'e5', 'f6']); // b2 has price exactly 20
});

test('maxPrice bound is inclusive', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { maxPrice: 30.5 });
  assert.deepEqual(ids(result), ['a1', 'b2', 'c3', 'd4']); // c3 has price exactly 30.5
});

test('minPrice === maxPrice keeps only exact-price items', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 10, maxPrice: 10 })), ['a1']);
});

test('price bounds with min 0 and max Infinity match everything', () => {
  const items = sampleItems();
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 0, maxPrice: Infinity })), ids(items));
});

test('float boundary: price 19.999 excluded by minPrice 20, included by 19.99', () => {
  const items = [{ id: 'f', name: 'x', price: 19.999 }];
  assert.deepEqual(searchCatalog(items, { minPrice: 20 }), []);
  assert.deepEqual(ids(searchCatalog(items, { minPrice: 19.99 })), ['f']);
});

// ---------------------------------------------------------------------------
// Order stability & input preservation
// ---------------------------------------------------------------------------

test('input order is preserved, not sorted by price or name', () => {
  const items = [
    { id: 'hi1', name: 'widget', price: 1000 },
    { id: 'lo1', name: 'Widget', price: 1 },
    { id: 'mid', name: 'WIDGET', price: 500 },
    { id: 'other', name: 'gizmo', price: 300 },
    { id: 'hi2', name: 'widgets', price: 999 },
  ];
  const result = searchCatalog(items, { query: 'widget' });
  assert.deepEqual(ids(result), ['hi1', 'lo1', 'mid', 'hi2']);
});

test('result is a new array but keeps references to the original item objects', () => {
  const items = sampleItems();
  const result = searchCatalog(items, { query: 'widget' });
  assert.notStrictEqual(result, items);
  assert.strictEqual(result[0], items[0]);
  assert.strictEqual(result[1], items[2]);
  assert.strictEqual(result[2], items[4]);
});

test('full match result is still a distinct array from the input', () => {
  const items = sampleItems();
  const result = searchCatalog(items);
  assert.notStrictEqual(result, items);
  assert.deepEqual(result, items);
});

test('input array and its objects are never mutated (deep equality before/after)', () => {
  const items = sampleItems();
  items[0].tags = ['keep', 'me']; // extra properties must survive untouched
  const snapshot = structuredClone(items);
  searchCatalog(items, { query: 'W', minPrice: 5, maxPrice: 50 });
  searchCatalog(items);
  searchCatalog(items, { query: 'no-such-thing' });
  assert.deepEqual(items, snapshot);
  // Order of input itself is unchanged:
  assert.deepEqual(ids(items), ['a1', 'b2', 'c3', 'd4', 'e5', 'f6']);
  // Result operations do not write back into the input:
  const result = searchCatalog(items, { query: 'widget' });
  result.push({ id: 'injected', name: 'junk', price: -1 });
  assert.equal(items.length, 6);
});

test('empty input array returns empty array', () => {
  const items = [];
  assert.deepEqual(searchCatalog(items, { query: 'anything' }), []);
  assert.deepEqual(searchCatalog(items), []);
});

// ---------------------------------------------------------------------------
// Invalid bounds rejection
// ---------------------------------------------------------------------------

test('negative minPrice throws Error', () => {
  assert.throws(() => searchCatalog([], { minPrice: -1 }), Error);
  assert.throws(() => searchCatalog([], { minPrice: -0.01 }), Error);
});

test('negative maxPrice throws Error', () => {
  assert.throws(() => searchCatalog([], { maxPrice: -5 }), Error);
});

test('NaN bounds throw Error', () => {
  assert.throws(() => searchCatalog([], { minPrice: NaN }), Error);
  assert.throws(() => searchCatalog([], { maxPrice: NaN }), Error);
});

test('non-numeric bounds throw Error', () => {
  for (const bad of ['10', true, false, {}, [], () => 5, null, Symbol.iterator]) {
    assert.throws(() => searchCatalog([], { minPrice: bad }), Error, `minPrice=${String(bad)}`);
    assert.throws(() => searchCatalog([], { maxPrice: bad }), Error, `maxPrice=${String(bad)}`);
  }
});

test('minPrice greater than maxPrice throws Error', () => {
  assert.throws(() => searchCatalog([], { minPrice: 50, maxPrice: 10 }), Error);
  assert.throws(() => searchCatalog([], { minPrice: 10.01, maxPrice: 10 }), Error);
});

test('minPrice === maxPrice is valid (not an inversion)', () => {
  assert.doesNotThrow(() => searchCatalog(sampleItems(), { minPrice: 10, maxPrice: 10 }));
});

test('Infinity is accepted as a bound (only rejected via min > max rule)', () => {
  assert.doesNotThrow(() => searchCatalog(sampleItems(), { maxPrice: Infinity }));
  assert.doesNotThrow(() => searchCatalog(sampleItems(), { minPrice: 0, maxPrice: Infinity }));
  assert.throws(() => searchCatalog([], { minPrice: Infinity, maxPrice: 100 }), Error);
});

test('errors are thrown before any filtering, even with items present', () => {
  const items = sampleItems();
  assert.throws(() => searchCatalog(items, { minPrice: -1, query: 'widget' }), (err) => {
    assert.ok(err instanceof Error);
    return true;
  });
});

// ---------------------------------------------------------------------------
// Invalid query / items arguments (interpretation decisions, see report)
// ---------------------------------------------------------------------------

test('non-string query throws Error', () => {
  for (const badQuery of [5, null, true, {}, [], NaN]) {
    assert.throws(() => searchCatalog(sampleItems(), { query: badQuery }), Error);
  }
});

test('non-array items throws Error', () => {
  for (const badItems of [null, undefined, 'nope', 42, { id: 'a' }]) {
    assert.throws(() => searchCatalog(badItems), Error);
  }
});

// ---------------------------------------------------------------------------
// Item-shape edge cases (documented interpretations)
// ---------------------------------------------------------------------------

test('items with missing/non-string name only match the empty query', () => {
  const items = [
    { id: 'n1', price: 5 },
    { id: 'n2', name: null, price: 5 },
    { id: 'n3', name: 123, price: 5 },
    { id: 'n4', name: '', price: 5 },
  ];
  assert.deepEqual(ids(searchCatalog(items)), ids(items)); // empty query matches all
  assert.deepEqual(searchCatalog(items, { query: 'x' }), []);
});

test('items with non-numeric price are excluded rather than throwing', () => {
  const items = [
    { id: 'ok', name: 'good', price: 10 },
    { id: 'bad1', name: 'good', price: 'ten' },
    { id: 'bad2', name: 'good' },
    { id: 'bad3', name: 'good', price: NaN },
  ];
  assert.deepEqual(ids(searchCatalog(items, { query: 'good' })), ['ok']);
});

test('Unicode case folding works for non-ASCII names', () => {
  const items = [{ id: 'u', name: 'Äpfel', price: 1 }];
  assert.deepEqual(ids(searchCatalog(items, { query: 'äpfel' })), ['u']);
  assert.deepEqual(ids(searchCatalog(items, { query: 'ÄPFEL' })), ['u']);
});

test('repeated calls with the same input are deterministic', () => {
  const items = sampleItems();
  const opts = { query: 'widget', minPrice: 5, maxPrice: 50 };
  assert.deepEqual(searchCatalog(items, opts), searchCatalog(items, opts));
});
